import{_ as e,o as t,c as o,a2 as d}from"./chunks/framework.D8Tso2Ul.js";const h=JSON.parse('{"title":"Módulo: Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/dashboard.md","filePath":"modulos/dashboard.md"}'),s={name:"modulos/dashboard.md"};function r(i,a,n,c,l,u){return t(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="modulo-dashboard" tabindex="-1">Módulo: Dashboard <a class="header-anchor" href="#modulo-dashboard" aria-label="Permalink to &quot;Módulo: Dashboard&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/pages/Dashboard.tsx</code></p><p>El Dashboard es el panel principal de la plataforma. Ofrece una vista de un vistazo del estado de seguridad de la obra activa, con indicadores clave (KPIs) y accesos directos a las acciones más frecuentes.</p><h2 id="indicadores-clave" tabindex="-1">Indicadores clave <a class="header-anchor" href="#indicadores-clave" aria-label="Permalink to &quot;Indicadores clave&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indicador</th><th>Qué mide</th></tr></thead><tbody><tr><td>Días sin accidentes</td><td>Días transcurridos desde el último accidente registrado</td></tr><tr><td>Trabajadores activos</td><td>Personas activas asignadas a la obra</td></tr><tr><td>Total de documentos</td><td>Documentos de la obra y su estado de cumplimiento</td></tr><tr><td>Actividades completadas</td><td>Charlas, capacitaciones y auditorías cerradas</td></tr></tbody></table><h2 id="vistas-y-accesos-rapidos" tabindex="-1">Vistas y accesos rápidos <a class="header-anchor" href="#vistas-y-accesos-rapidos" aria-label="Permalink to &quot;Vistas y accesos rápidos&quot;">​</a></h2><ul><li><strong>Resumen de cumplimiento por fase</strong>: porcentaje de documentos obligatorios firmados en la fase actual de la obra.</li><li><strong>Pendientes</strong>: documentos asignados sin firmar y actividades programadas próximas.</li><li><strong>Últimos incidentes</strong>: acceso directo al detalle de los eventos más recientes.</li><li><strong>Selector de obra</strong>: cuando una persona pertenece a varias obras, puede cambiar el contexto activo (ver <code>ObraContext</code>).</li></ul><h2 id="contexto-de-obra" tabindex="-1">Contexto de obra <a class="header-anchor" href="#contexto-de-obra" aria-label="Permalink to &quot;Contexto de obra&quot;">​</a></h2><p>El Dashboard depende de la <strong>obra activa</strong> seleccionada en <code>ObraContext</code>. Los KPIs y listados se filtran por esa obra y por el <code>tenantId</code> de la sesión, garantizando el <a href="/manual/arquitectura/multi-tenant.html">aislamiento multi-tenant</a>.</p><h2 id="acceso-por-rol" tabindex="-1">Acceso por rol <a class="header-anchor" href="#acceso-por-rol" aria-label="Permalink to &quot;Acceso por rol&quot;">​</a></h2><p>El Dashboard es accesible para todos los roles, pero el contenido se adapta:</p><table tabindex="0"><thead><tr><th>Rol</th><th>Qué ve</th></tr></thead><tbody><tr><td>Admin / Jefe de Obra</td><td>Visión completa de la obra y KPIs agregados</td></tr><tr><td>Prevencionista</td><td>Cumplimiento documental, incidentes, actividades</td></tr><tr><td>Supervisor</td><td>Estado de su equipo y firmas pendientes</td></tr><tr><td>Trabajador</td><td>Sus documentos pendientes y actividades asignadas</td></tr></tbody></table><p>Ver detalle de permisos en <a href="/manual/roles/">Roles de Usuario</a>.</p>',13)])])}const b=e(s,[["render",r]]);export{h as __pageData,b as default};
